namespace Tests.System.Reactive.Shared;

/// <summary>
/// Describes <c>Seq.FromEvent(addHandler, removeHandler[, scheduler])</c> over an
/// <c>Action&lt;TEventArgs&gt;</c> event.
/// </summary>
/// <typeparam name="TEventArgs">The type of the event data generated by the event.</typeparam>
/// <remarks>
/// Built by the <c>Seq.FromEvent</c> overloads in <c>Seq.FromEvent.cs</c>; materialized by each
/// target through <see cref="ISeqVisitor.FromEvent{TEventArgs}(FromEventSeq{TEventArgs})"/>.
/// </remarks>
public sealed class FromEventSeq<TEventArgs>(Action<Action<TEventArgs>> addHandler, Action<Action<
        TEventArgs>> removeHandler, SchedulerRef? scheduler)
    : Seq<TEventArgs>
{
    /// <summary>
    /// Action that attaches the given event handler to the underlying .NET event.
    /// </summary>
    public Action<Action<TEventArgs>> AddHandler => addHandler;

    /// <summary>
    /// Action that detaches the given event handler from the underlying .NET event.
    /// </summary>
    public Action<Action<TEventArgs>> RemoveHandler => removeHandler;

    /// <summary>
    /// Scheduler to run the event conversion on, or null for the target's default.
    /// </summary>
    public SchedulerRef? Scheduler => scheduler;

    /// <inheritdoc/>
    protected override Realized<Seq<TEventArgs>> AcceptCore(ISeqVisitor visitor) =>
        visitor.FromEvent(this);

    /// <inheritdoc/>
    public override string ToString() =>
        scheduler is null
            ? "Seq.FromEvent(addHandler, removeHandler)"
            : $"Seq.FromEvent(addHandler, removeHandler, {scheduler})";
}
